mapper.select:
SELECT sm.id, sm.shop_id, si.name AS shopName, sm.platform_dict, sm.platform_name, sm.product_sku_id, sm.product_sku_no, sm.platform_sku_no, sm.platform_sku_name, sm.match_result, sm.create_user_name, sm.create_time FROM sku_maping sm INNER JOIN shop_info si ON sm.shop_id=si.id AND si.is_deleted=FALSE WHERE sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.match_result=#{matchResult}
AND sm.shop_id IN
#{shopId}
AND sm.platform_dict IN
#{platform}
AND sm.product_sku_no IN
#{skuNo}
AND sm.create_user_id IN
#{createUserId}
AND sm.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sm.create_time
ORDER BY sm.create_time DESC

SELECT sm.id, sm.shop_id, si.name AS shopName, sm.platform_dict, sm.platform_name, sm.product_sku_id, sm.product_sku_no, sm.platform_sku_no, sm.platform_sku_name, sm.match_result, sm.create_user_name, sm.create_time FROM sku_maping sm INNER JOIN shop_info si ON sm.shop_id=si.id AND si.is_deleted=FALSE WHERE sm.is_deleted=FALSE AND sm.is_expire = FALSE
AND sm.id IN
#{id}
AND sm.match_result=#{matchResult}
AND sm.shop_id IN
#{shopId}
AND sm.product_sku_no IN
#{skuNo}
AND sm.platform_dict IN
#{platform}
AND sm.create_user_id IN
#{createUserId}
AND sm.create_time >= #{params.createTimeList[0]} and (#{params.createTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > sm.create_time
ORDER BY sm.create_time DESC

SELECT match_result, count(*) FROM sku_maping WHERE is_deleted=FALSE AND is_expire = FALSE
${permissionSql}
GROUP BY match_result

SELECT product_sku_id AS skuId, product_sku_no AS skuNo, platform_sku_no, platform_sku_name FROM sku_maping sm INNER JOIN shop_info si ON sm.shop_id=si.id and si.is_deleted=FALSE WHERE sm.is_deleted=FALSE AND sm.is_expire=FALSE AND si.customer_code=(SELECT code FROM customer_info WHERE id=#{params.customerId})
AND ( sm.product_sku_no ILIKE concat('%', #{params.no} ,'%') OR sm.platform_sku_no ILIKE concat('%', #{params.no} ,'%') )
AND (sm.product_sku_no IN
#{skuNo}
OR sm.platform_sku_no IN
#{skuNo}
)
